import heapq

def find_kth_smallest(arr, K):
    bin_heap = [-v for v in arr[:K]]   # max-heap via negation
    heapq.heapify(bin_heap)
    for v in arr[K:]:
        if v < -bin_heap[0]:
            heapq.heapreplace(bin_heap, -v)
    return -bin_heap[0]

