#include <bits/stdc++.h>
using namespace std;

int findKthSmallest(vector<int>& arr, int K) {
    priority_queue<int> pq;  // max-heap of the K smallest so far
    for (int i = 0; i < (int)arr.size(); ++i) {
        if ((int)pq.size() < K) { pq.push(arr[i]); continue; }
        if (arr[i] < pq.top()) { pq.pop(); pq.push(arr[i]); }
    }
    return pq.top();
}

